_previous_create_dicke_state = create_dicke_state
_previous_create_dicke_state_adaptive = create_dicke_state_adaptive
bell_layout_mode = "mean"
use_shallow_main = True
use_native_main = True
use_calibrated_choices = True
use_small_layout = True


def small_templates(n_q, k, flip=False):
    logical = cirq.LineQubit.range(n_q)
    templates = []
    if k == 1:
        if n_q == 3:
            trees = ((0, {0: [1], 1: [2]}), (1, {1: [0, 2]}))
        else:
            trees = ((1, {1: [2, 0], 2: [3]}),
                     (0, {0: [1], 1: [2], 2: [3]}),
                     (0, {0: [1, 2, 3]}))
        for root, branches in trees:
            children = collections.defaultdict(list)
            for parent, offspring in branches.items():
                children[logical[parent]] = [logical[j] for j in offspring]
            templates.append(compile_circuit(w_ops(logical[root], children),
                                               logical if flip else (), False))
    else:
        for table in (patches, shallow_patches):
            patch = table.get((n_q, k))
            if patch:
                templates.append(compile_circuit(patch_ops(logical, *patch[1:]),
                                                   logical if flip else (), False))
    return [(circuit, logical) for circuit in templates]


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    n_q, n = int(num_qubits), int(num_excitations)
    if n_q < 1 or not 0 <= n <= n_q:
        raise NotImplementedError(f"invalid (N, n) = ({n_q}, {n})")
    calibration = (cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
    if (n_q, n) == (2, 1) and not pack and bell_layout_mode == "mean":
        best = None
        for alternate in (False, True):
            pairs, pz, px = _bell_probabilities(calibration, alternate)
            scores = _bell_scores(pz, px)
            index = int(np.argmax(scores))
            if best is None or scores[index] > best[0]:
                best = scores[index], pairs[index], alternate
        _, (root, child), alternate = best
        if alternate:
            ops = [cirq.X(root), cirq.H(root), cirq.H(child), cirq.CZ(root, child),
                   cirq.X(child), cirq.H(child), cirq.X(child)]
        else:
            children = collections.defaultdict(list)
            children[root].append(child)
            ops = w_ops(root, children)
        circuit = compile_circuit(ops, dynamical_decoupling=dynamical_decoupling)
        check_circuit(circuit, cz_pauli_error_rate, sq_pauli_error_rate)
        return circuit, {root, child}
    if use_small_layout and n_q in (3, 4) and 0 < n < n_q and not pack:
        templates = small_templates(n_q, min(n, n_q - n), n > n_q - n)
        circuit, qubits = choose_small(templates, calibration, n_q, n)
        check_circuit(circuit, cz_pauli_error_rate, sq_pauli_error_rate)
        return circuit, qubits
    k = min(n, n_q - n)
    candidate = shallow_patches.get((n_q, k)) if use_shallow_main else None
    native = native_circuits.get((n_q, k)) if use_native_main and k >= 2 else None
    try:
        circuit, qubits = _previous_create_dicke_state(n_q, n, *calibration,
                                                       dynamical_decoupling=dynamical_decoupling,
                                                       pack=pack, use_blocks=use_blocks)
    except NotImplementedError:
        if candidate is None and native is None:
            raise
        circuit, qubits = None, None
    if candidate is None and native is None:
        return circuit, qubits
    adj, node = make_chip(*calibration, n_q, n)
    skew = {q: rate(one_errors[q]) - rate(zero_errors[q]) for q in node}
    bias = lambda qs: readout_bias(qs, n_q, n, skew)
    alternatives = []
    if candidate is not None:
        lab = best_patch(adj, node, candidate[0], candidate[1], bias)
        if lab is not None:
            alternatives.append((lab, patch_ops(lab, *candidate[1:])))
    if native is not None:
        origin = native[0][0]
        cells = [(a - origin[0], b - origin[1]) for a, b in native[0]]
        edges = [tuple(item) for layer in native[1] for item in layer if len(item) == 2]
        lab = best_patch(adj, node, cells, edges, bias)
        if lab is not None:
            decoded, _ = native_decode(native, lab)
            alternatives.append((lab, list(decoded.all_operations())))
    def rank(item, labels):
        if pack:
            return -len(item)
        if use_calibrated_choices and n_q <= 8:
            return circuit_score(item, labels, calibration, n)
        return -estimate_error(item, labels, adj, node, bias)
    best_score = rank(circuit, qubits) if circuit is not None else -float("inf")
    seen = {cirq.FrozenCircuit(circuit)} if circuit is not None else set()
    for lab, operations in alternatives:
        alternate = compile_circuit(operations, lab if n > n_q - n else (),
                                     dynamical_decoupling=dynamical_decoupling and not pack, pack=pack)
        frozen = cirq.FrozenCircuit(alternate)
        if frozen in seen:
            continue
        seen.add(frozen)
        score = rank(alternate, lab)
        if score > best_score:
            check_circuit(alternate, cz_pauli_error_rate, sq_pauli_error_rate)
            circuit, qubits, best_score = alternate, set(lab), score
    if circuit is None:
        raise NotImplementedError("no calibrated layout found")
    return circuit, qubits


def create_dicke_state_adaptive(num_qubits, num_excitations):
    n_q, n = int(num_qubits), int(num_excitations)
    candidate = shallow_patches.get((n_q, min(n, n_q - n)))
    if candidate is None:
        return _previous_create_dicke_state_adaptive(n_q, n)
    metadata = cirq_google.Willow105.metadata
    nodes = {q: 0.0 for q in sorted(metadata.qubit_set)}
    adjacency = collections.defaultdict(dict)
    for a, b in metadata.qubit_pairs:
        adjacency[a][b] = adjacency[b][a] = 0.0
    lab = best_patch(adjacency, nodes, candidate[0], candidate[1])
    if lab is None:
        return _previous_create_dicke_state_adaptive(n_q, n)
    circuit = compile_circuit(patch_ops(lab, *candidate[1:]), lab if n > n_q - n else (),
                               dynamical_decoupling=False, pack=True)
    return circuit, set(lab)


_uncached_create_dicke_state_adaptive = create_dicke_state_adaptive


def native_decode(record, qubits=None):
    coords, layers = record
    qubits = [cirq.GridQubit(*xy) for xy in coords] if qubits is None else list(qubits)
    moments = []
    for layer in layers:
        operations = []
        for item in layer:
            if len(item) == 2:
                operations.append(cirq.CZ(qubits[item[0]], qubits[item[1]]))
            else:
                q, x, z, axis = item
                operations.append(cirq.PhasedXZGate(x_exponent=x, z_exponent=z,
                                                    axis_phase_exponent=axis).on(qubits[q]))
        moments.append(cirq.Moment(operations))
    return cirq.Circuit(moments), qubits


def create_dicke_state_adaptive(num_qubits, num_excitations):
    n_q, n = int(num_qubits), int(num_excitations)
    if n_q < 1 or not 0 <= n <= n_q:
        raise NotImplementedError(f"invalid (N, n) = ({n_q}, {n})")
    record = native_circuits.get((n_q, min(n, n_q - n)))
    if record is None:
        return _uncached_create_dicke_state_adaptive(n_q, n)
    circuit, qubits = native_decode(record)
    if n > n_q - n:
        circuit = compile_circuit(circuit.all_operations(), qubits, False, True)
    return circuit, set(qubits)


