_upgrade_previous_create = create_dicke_state


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    circuit, qubits = _upgrade_previous_create(num_qubits, num_excitations, cz_pauli_error_rate,
                                               sq_pauli_error_rate, zero_errors, one_errors,
                                               dynamical_decoupling, pack, use_blocks)
    n, k = int(num_qubits), int(num_excitations)
    record = _upgrade_patches.get((n, k))
    if record is None or not dynamical_decoupling or pack or not use_blocks:
        return circuit, qubits
    calibration = (cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
    adj, node = make_chip(*calibration, n, k)
    skew = {q: rate(one_errors[q]) - rate(zero_errors[q]) for q in node}
    bias = lambda qs: readout_bias(qs, n, k, skew)
    kind, coords, edges, angles, zs = record
    if kind == 'line':
        weights = [0] * (n - 1)
        for a, b in edges:
            weights[min(a, b)] += 1
        labels = best_path(adj, node, weights, time.monotonic() + 1.0, bias)
    else:
        labels = best_patch(adj, node, coords, edges, bias)
    if labels is not None:
        alternate = compile_circuit(patch_ops(labels, edges, angles, zs),
                                      dynamical_decoupling=True, pack=False)
        if circuit_score(alternate, labels, calibration, k) > circuit_score(circuit, qubits, calibration, k) + 1e-8:
            check_circuit(alternate, cz_pauli_error_rate, sq_pauli_error_rate)
            return alternate, set(labels)
    return circuit, qubits


