def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    key = str(int(num_qubits)) + "," + str(int(num_excitations))
    if key in _extra_tables and dynamical_decoupling and not pack and use_blocks:
        calibration = (cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
        _, _, circuit, qs, _ = _response_select(_extra_baseline, _extra_tables[key], calibration)
        check_circuit(circuit, cz_pauli_error_rate, sq_pauli_error_rate)
        return circuit, set(qs)
    return _extra_previous_create(num_qubits, num_excitations, cz_pauli_error_rate,
                                   sq_pauli_error_rate, zero_errors, one_errors,
                                   dynamical_decoupling, pack, use_blocks)


