_final_previous_adaptive = create_dicke_state_adaptive


def create_dicke_state_adaptive(num_qubits, num_excitations):
    n, k = int(num_qubits), int(num_excitations)
    record = _final_native.get((n, min(k, n - k)))
    if record is None:
        return _final_previous_adaptive(n, k)
    circuit, labels = native_decode(record)
    if k > n - k:
        circuit = compile_circuit(circuit.all_operations(), labels, False, True)
    return circuit, set(labels)


_main_native_previous_create = create_dicke_state
_main_native_cases = {(6, 2), (6, 3), (7, 2), (7, 3), (8, 2)}


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    circuit, qubits = _main_native_previous_create(num_qubits, num_excitations, cz_pauli_error_rate,
                                                  sq_pauli_error_rate, zero_errors, one_errors,
                                                  dynamical_decoupling, pack, use_blocks)
    n, k = int(num_qubits), int(num_excitations)
    if (n, k) not in _main_native_cases or not dynamical_decoupling or pack or not use_blocks:
        return circuit, qubits
    record = _final_native[n, k]
    calibration = (cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
    adj, node = make_chip(*calibration, n, k)
    skew = {q: rate(one_errors[q]) - rate(zero_errors[q]) for q in node}
    bias = lambda qs: readout_bias(qs, n, k, skew)
    edges = [tuple(item) for layer in record[1] for item in layer if len(item) == 2]
    neighbours = {j: set() for j in range(n)}
    counts = collections.Counter(tuple(sorted(edge)) for edge in edges)
    for a, b in counts:
        neighbours[a].add(b)
        neighbours[b].add(a)
    endpoints = [q for q in neighbours if len(neighbours[q]) == 1]
    if len(counts) == n - 1 and len(endpoints) == 2 and max(map(len, neighbours.values())) <= 2:
        order = [min(endpoints)]
        while len(order) < n:
            order.append(next(q for q in neighbours[order[-1]] if q not in order))
        weights = [counts[tuple(sorted((a, b)))] for a, b in zip(order, order[1:])]
        path = best_path(adj, node, weights, time.monotonic() + 1., bias)
        labels = None
        if path is not None:
            labels = [None] * n
            for logical, physical in zip(order, path):
                labels[logical] = physical
    else:
        origin = record[0][0]
        cells = [(a - origin[0], b - origin[1]) for a, b in record[0]]
        labels = best_patch(adj, node, cells, edges, bias)
    if labels is None:
        return circuit, qubits
    native, _ = native_decode(record, labels)
    dressed = compile_circuit(native.all_operations(), dynamical_decoupling=True, pack=False)
    score = circuit_score(circuit, qubits, calibration, k)
    seen = {cirq.FrozenCircuit(circuit)}
    for alternate in (native, dressed):
        frozen = cirq.FrozenCircuit(alternate)
        if frozen in seen:
            continue
        seen.add(frozen)
        value = circuit_score(alternate, labels, calibration, k)
        if value > score + 1e-8:
            check_circuit(alternate, cz_pauli_error_rate, sq_pauli_error_rate)
            circuit, qubits, score = alternate, set(labels), value
    return circuit, qubits


#bonus: portfolio circuits plus the moment squeeze from toby/bonus_squeeze_sol.py
import cirq_google
_portfolio_create_dicke_state_adaptive = create_dicke_state_adaptive


def _squeeze_variants(circuit):
    #z rotations commute with cz, so ejecting them and re-merging the 1q gates can empty whole moments
    for eject in (lambda c: c, cirq.eject_z, lambda c: cirq.eject_phased_paulis(cirq.eject_z(c)),
                  lambda c: cirq.eject_z(cirq.eject_phased_paulis(c))):
        c = cirq.drop_empty_moments(cirq.drop_negligible_operations(cirq.merge_single_qubit_gates_to_phxz(eject(circuit))))
        for align in (cirq.align_left, cirq.align_right, lambda x: cirq.Circuit(x.all_operations())):
            yield cirq.drop_empty_moments(cirq.merge_single_qubit_gates_to_phxz(cirq.drop_empty_moments(align(c))))


def create_dicke_state_adaptive(num_qubits, num_excitations):
    #portfolio (exp/depth-search 4df75cc), then keep the shortest rescheduled copy that is native, routed and gives the same state
    circuit, qubits = _portfolio_create_dicke_state_adaptive(num_qubits, num_excitations)
    device = getattr(cirq_google, "Willow105", None)
    if device is None or num_qubits > 20:
        return circuit, qubits
    order = sorted(circuit.all_qubits())
    ref = cirq.final_state_vector(circuit, qubit_order=order, dtype=np.complex128)
    best = circuit
    for cand in _squeeze_variants(circuit):
        if len(cand) >= len(best) or set(cand.all_qubits()) - set(order):
            continue
        if not all(op.gate == cirq.CZ or isinstance(op.gate, cirq.PhasedXZGate) for op in cand.all_operations()):
            continue
        try:
            device.validate_circuit(cand)
        except ValueError:
            continue
        psi = cirq.final_state_vector(cand, qubit_order=order, dtype=np.complex128)
        if abs(np.vdot(ref, psi)) > 1 - 1e-7:
            best = cand
    return best, qubits
